// Offline-first: the app shell, stories, lexicon and fonts are cached so a
// parent can practise with no data plan. (Story generation needs a connection.)
// Network first, so testers always get the newest build when they are online.

// BEGIN GENERATED by site/build.mjs: the cache name changes with every build.
const CACHE = 'hearth-bf3da84';
const SHELL = [
  './',
  './manifest.webmanifest',
  './assets/fonts/Andika-400-normal.woff2',
  './assets/fonts/Andika-700-normal.woff2',
  './assets/fonts/AtkinsonHyperlegible-400-normal.woff2',
  './assets/fonts/AtkinsonHyperlegible-700-normal.woff2',
  './assets/fonts/Fraunces-var.woff2',
  './assets/fonts/fonts.css',
  './assets/hearth-mark.svg',
  './assets/icon-192.png',
  './css/app.css',
  './data/lexicon.json',
  './data/stories.js',
  './data/talk-es.js',
  './engine/align.js',
  './engine/decodable.js',
  './engine/learner.js',
  './engine/lexicon.js',
  './engine/phonics.js',
  './engine/safety.js',
  './engine/simulate.js',
  './engine/text.js',
  './engine/tracker.js',
  './js/art.js',
  './js/brand.js',
  './js/config.js',
  './js/demo.js',
  './js/feedback.js',
  './js/household.js',
  './js/i18n.js',
  './js/install-sheet.js',
  './js/install.js',
  './js/keepsakes.js',
  './js/main.js',
  './js/router.js',
  './js/screens/home.js',
  './js/screens/library.js',
  './js/screens/onboarding.js',
  './js/screens/reader.js',
  './js/screens/settings.js',
  './js/screens/sky.js',
  './js/screens/warmup.js',
  './js/store.js',
  './js/stories.js',
  './js/ui.js',
  './js/voice.js',
  './js/wordbank.js',
];
// END GENERATED

// The app itself (everything in SHELL) is served from this phone's copy, so it
// opens instantly and offline, and costs no hosting traffic. The browser checks
// sw.js for a new build on each launch; a new build re-downloads the shell once,
// then the app switches to it on the next calm screen (see main.js).
const SHELL_URLS = new Set(SHELL.map(u => new URL(u, self.registration.scope).href));

self.addEventListener('install', e => e.waitUntil(
  caches.open(CACHE).then(c => c.addAll(SHELL.map(u => new Request(u, { cache: 'reload' })))).then(() => self.skipWaiting()),
));
self.addEventListener('activate', e => e.waitUntil(
  caches.keys().then(ks => Promise.all(ks.filter(k => k.startsWith('hearth-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()),
));

async function networkFirst(req) {
  try {
    const res = await fetch(req);
    if (res.ok && !res.redirected) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  } catch {
    return (await caches.match(req)) || Response.error();
  }
}

self.addEventListener('fetch', e => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || url.pathname.includes('/api/')) return;
  const appRoot = req.mode === 'navigate' && url.pathname === new URL(self.registration.scope).pathname; // also /product/?demo
  const key = appRoot ? new URL('./', self.registration.scope).href : url.origin + url.pathname;
  if (appRoot || SHELL_URLS.has(key)) {
    e.respondWith(caches.match(key, { ignoreSearch: true }).then(hit => hit || networkFirst(req)));
    return;
  }
  e.respondWith(networkFirst(req)); // studio, dashboard, website files: fresh when online
});
